// Parse and validate Gemini response for expense data
try {
  const geminiResponse = $input.first().json.response;

  // Try to extract JSON from the response
  let extractedData;

  if (typeof geminiResponse === 'string') {
    // Remove any markdown code blocks or extra text
    const jsonMatch = geminiResponse.match(/```json\s*([\s\S]*?)\s*```/) || 
                     geminiResponse.match(/\{[\s\S]*\}/);

    if (jsonMatch) {
      extractedData = JSON.parse(jsonMatch[1] || jsonMatch[0]);
    } else {
      throw new Error('No valid JSON found in response');
    }
  } else {
    extractedData = geminiResponse;
  }

  // Validate and structure expense data
  const validatedData = {
    receiptNumber: extractedData.receiptNumber || null,
    expenseDate: extractedData.expenseDate || null,
    expenseAmount: extractedData.expenseAmount ? Number(extractedData.expenseAmount) : null,
    currency: extractedData.currency || null,
    expenseType: extractedData.expenseType || null,
    description: extractedData.description || null,

    // Vendor information
    vendorName: extractedData.vendorName || null,
    vendorAddress: extractedData.vendorAddress || null,
    vendorPhone: extractedData.vendorPhone || null,
    vendorTaxId: extractedData.vendorTaxId || null,

    // Employee information
    employeeName: extractedData.employeeName || null,
    employeeId: extractedData.employeeId || null,
    department: extractedData.department || null,
    costCenter: extractedData.costCenter || null,

    // Business context
    purpose: extractedData.purpose || null,
    clientName: extractedData.clientName || null,
    projectCode: extractedData.projectCode || null,
    isClientReimbursable: extractedData.isClientReimbursable || null,

    // Tax information
    taxAmount: extractedData.taxAmount ? Number(extractedData.taxAmount) : null,
    taxRate: extractedData.taxRate ? Number(extractedData.taxRate) : null,
    taxType: extractedData.taxType || null,
    isTaxDeductible: extractedData.isTaxDeductible || null,

    // Travel details
    travelDetails: {
      origin: extractedData.travelDetails?.origin || null,
      destination: extractedData.travelDetails?.destination || null,
      distance: extractedData.travelDetails?.distance ? Number(extractedData.travelDetails.distance) : null,
      transportMode: extractedData.travelDetails?.transportMode || null,
      mileageRate: extractedData.travelDetails?.mileageRate ? Number(extractedData.travelDetails.mileageRate) : null
    },

    // Meal details
    mealDetails: {
      attendees: extractedData.mealDetails?.attendees || null,
      attendeeCount: extractedData.mealDetails?.attendeeCount ? Number(extractedData.mealDetails.attendeeCount) : null,
      mealType: extractedData.mealDetails?.mealType || null,
      isClientMeal: extractedData.mealDetails?.isClientMeal || null
    },

    additionalDetails: extractedData.additionalDetails || {},
    confidence: extractedData.confidence || 0.5
  };

  // Add business rule validations
  if (validatedData.expenseAmount && validatedData.taxAmount) {
    const calculatedSubtotal = validatedData.expenseAmount - validatedData.taxAmount;
    validatedData.additionalDetails.subtotal = calculatedSubtotal;
  }

  // Auto-detect expense type if not provided
  if (!validatedData.expenseType && validatedData.vendorName) {
    const vendor = validatedData.vendorName.toLowerCase();
    if (vendor.includes('restaurant') || vendor.includes('cafe') || vendor.includes('food')) {
      validatedData.expenseType = 'meal';
    } else if (vendor.includes('hotel') || vendor.includes('motel')) {
      validatedData.expenseType = 'accommodation';
    } else if (vendor.includes('gas') || vendor.includes('fuel') || vendor.includes('shell') || vendor.includes('exxon')) {
      validatedData.expenseType = 'fuel';
    } else if (vendor.includes('taxi') || vendor.includes('uber') || vendor.includes('lyft')) {
      validatedData.expenseType = 'transport';
    }
  }

  return {
    success: true,
    extractedData: validatedData,
    confidence: validatedData.confidence,
    processedAt: new Date().toISOString(),
    documentId: $('Webhook Trigger').first().json.body.documentId
  };

} catch (error) {
  return {
    success: false,
    error: `Expense data processing failed: ${error.message}`,
    processedAt: new Date().toISOString(),
    documentId: $('Webhook Trigger').first().json.body.documentId
  };
}

// Process final expense claim submission
const expenseData = $input.first().json.body;

// Generate a unique expense claim ID
const claimId = `EXP-${Date.now()}-${Math.random().toString(36).substr(2, 9).toUpperCase()}`;

// Structure the final expense submission
const finalExpenseClaim = {
  claimId: claimId,
  submissionDate: new Date().toISOString(),
  status: 'submitted',
  claimType: 'expense',
  documents: expenseData.documents || [],
  extractedData: expenseData.extractedData || {},
  userVerified: expenseData.userVerified || false,
  processingNotes: {
    submittedVia: 'web-portal',
    aiProcessed: true,
    documentsCount: (expenseData.documents || []).length,
    averageConfidence: expenseData.extractedData?.confidence || 0,
    expenseType: expenseData.extractedData?.expenseType || 'other',
    totalAmount: expenseData.extractedData?.expenseAmount || 0,
    currency: expenseData.extractedData?.currency || 'USD'
  },
  // Add expense-specific fields for easy reporting
  summary: {
    employeeName: expenseData.extractedData?.employeeName,
    department: expenseData.extractedData?.department,
    expenseType: expenseData.extractedData?.expenseType,
    amount: expenseData.extractedData?.expenseAmount,
    currency: expenseData.extractedData?.currency,
    expenseDate: expenseData.extractedData?.expenseDate,
    vendorName: expenseData.extractedData?.vendorName,
    purpose: expenseData.extractedData?.purpose,
    isClientReimbursable: expenseData.extractedData?.isClientReimbursable || false
  }
};

// Add approval workflow logic
let approvalRequired = false;
const amount = expenseData.extractedData?.expenseAmount || 0;

// Set approval thresholds
if (amount > 500) {
  approvalRequired = true;
  finalExpenseClaim.status = 'pending_approval';
  finalExpenseClaim.processingNotes.approvalReason = 'Amount exceeds $500 threshold';
} else if (expenseData.extractedData?.expenseType === 'entertainment') {
  approvalRequired = true;
  finalExpenseClaim.status = 'pending_approval';
  finalExpenseClaim.processingNotes.approvalReason = 'Entertainment expenses require approval';
}

// Log the submission (in production, this would go to your expense management system)
console.log('New expense claim submitted:', finalExpenseClaim);

return {
  success: true,
  claimId: claimId,
  message: approvalRequired ? 'Expense claim submitted for approval' : 'Expense claim submitted successfully',
  status: finalExpenseClaim.status,
  approvalRequired: approvalRequired,
  submittedAt: finalExpenseClaim.submissionDate,
  summary: finalExpenseClaim.summary
};
